async function fixture(t,options={}) {
  let time=Date.parse('2026-09-13T04:00:00Z');
  const api=createApi({dbPath:':memory:',now:()=>time,...options});
  const server=createServer((req,res)=>{options.observeRequest?.(req);api.handle(req,res).then(handled=>{if(!handled){res.statusCode=404;res.end();}});});
  await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
  const base=`http://127.0.0.1:${server.address().port}`;
  t.after(async()=>{await new Promise(resolve=>server.close(resolve));api.close();});
  function client(){let cookie='';return {async call(path,method='GET',body,custom={}){const headers={...(cookie?{Cookie:cookie}:{}),...(method==='GET'?{}:{Origin:base,'Content-Type':'application/json'}),...custom};const res=await fetch(base+path,{method,headers,...(body!==undefined?{body:JSON.stringify(body)}:{})});const next=res.headers.get('set-cookie');if(next)cookie=next.split(';')[0];return {status:res.status,headers:res.headers,body:await res.json()};},get cookie(){return cookie;}};}
  return {client,advance:ms=>time+=ms,api,base};
}

test('all four education networks are server authorization boundaries for every object type',async t=>{
  const f=await fixture(t),clients={},states={};
  for(const network of NETWORKS){clients[network]=f.client();assert.equal((await clients[network].call('/api/demo','POST',{network})).status,200);states[network]=(await clients[network].call('/api/state')).body;assert.ok(states[network].activities.length>=8);for(const item of [...states[network].activities,...states[network].people,...states[network].circles,...states[network].tutors])assert.equal(item.network,network);assert.equal(states[network].meta.network,network);}
  for(const network of NETWORKS){for(const foreign of NETWORKS.filter(x=>x!==network)){
    const client=clients[network],s=states[foreign];
    const cases=[['/api/activities/'+s.activities[0].id,'GET'],['/api/activities/'+s.activities[0].id+'/join','POST',{}],['/api/activities/'+s.activities[0].id+'/save','POST',{}],['/api/circles/'+s.circles[0].id+'/join','POST',{}],['/api/connections','POST',{personId:s.people[0].id,action:'connect'}],['/api/messages/'+s.people[0].id,'GET'],['/api/messages/'+s.people[0].id,'POST',{text:'Hello'}],['/api/tutors/'+s.tutors[0].id+'/request','POST',{date:'2026-09-15',time:'15:00'}],['/api/blocks','POST',{personId:s.people[0].id}],['/api/reports','POST',{targetId:s.activities[0].id,reason:'Unsafe'}],['/api/telegram/consent','POST',{personId:s.people[0].id,consent:true}]];
    for(const args of cases){const result=await client.call(...args);assert.equal(result.status,404,`${network} → ${foreign} ${args[0]}: ${JSON.stringify(result.body)}`);}
  }}
});

test('origin/session checks and immutable identity prevent request tampering',async t=>{
  const f=await fixture(t),c=f.client();assert.equal((await c.call('/api/state')).status,401);
  assert.equal((await c.call('/api/demo','POST',{}, {Origin:'https://evil.example'})).status,403);
  const login=await c.call('/api/demo','POST',{});assert.match(login.headers.get('set-cookie'),/HttpOnly; SameSite=Lax/);assert.equal(c.cookie.length,77);
  assert.equal((await c.call('/api/profile','PATCH',{network:'university'})).status,400);
  assert.equal((await c.call('/api/profile','PATCH',{institutionId:'nus'})).status,400);
  assert.equal((await c.call('/api/profile','PATCH',{ageBand:'under18'})).status,400);
  assert.equal((await c.call('/api/profile','PATCH',{bio:'Text me at 9123 4567'})).status,400);
  const state=(await c.call('/api/state')).body;assert.ok(!('email' in state.people[0]));assert.ok(!('ageBand' in state.people[0]));assert.ok(!('telegramUsername' in state.people[0]));assert.ok(!('settings' in state.people[0]));
  assert.equal((await c.call('/api/logout','POST',{})).status,200);assert.equal((await c.call('/api/state')).status,401);
});

test('activities persist, require public network locations and enforce idempotent capacity',async t=>{
  const f=await fixture(t),c=f.client();await c.call('/api/demo','POST',{});const locs=(await c.call('/api/locations')).body.locations;assert.ok(locs.every(x=>x.network==='polytechnic'));
  const input={category:'sports',title:'Friendly doubles',description:'Bring a racket and meet at the sports centre.',date:'2026-09-14',time:'17:30',locationId:locs[0].id,capacity:2};
  assert.equal((await c.call('/api/activities','POST',{...input,network:'university'})).status,403);
  assert.equal((await c.call('/api/activities','POST',{...input,locationId:'nus-library'})).status,400);
  assert.equal((await c.call('/api/activities','POST',{...input,locationId:'home-address'})).status,400);
  assert.equal((await c.call('/api/activities','POST',{...input,date:'2026-02-31'})).status,400);
  const created=await c.call('/api/activities','POST',input);assert.equal(created.status,201);assert.equal(created.body.activity.network,'polytechnic');assert.equal(created.body.activity.participants.length,1);
  const other=f.client();const otp=await other.call('/api/auth/start','POST',{institutionId:'sp',email:'second@ichat.sp.edu.sg',ageBand:'18plus'});assert.equal(otp.status,200);await other.call('/api/auth/verify','POST',{challengeId:otp.body.challengeId,code:otp.body.demoCode});
  const url='/api/activities/'+created.body.activity.id;assert.equal((await other.call(url+'/join','POST',{})).status,200);const repeated=await other.call(url+'/join','POST',{});assert.equal(repeated.status,200);assert.equal(repeated.body.activity.participants.length,2);
  const third=f.client(),otp3=await third.call('/api/auth/start','POST',{institutionId:'np',email:'third@connect.np.edu.sg'});await third.call('/api/auth/verify','POST',{challengeId:otp3.body.challengeId,code:otp3.body.demoCode});assert.equal((await third.call(url+'/join','POST',{})).status,409);
  assert.equal((await other.call(url+'/leave','POST',{})).status,200);assert.equal((await third.call(url+'/join','POST',{})).status,200);
  const saved=await third.call(url+'/save','POST',{});assert.equal(saved.body.activity.saved,true);assert.equal((await third.call(url+'/save','POST',{})).body.activity.saved,false);
});

test('mutual consent gates messaging, blocks apply in both directions and no contact leaks',async t=>{
  const f=await fixture(t),c=f.client();await c.call('/api/demo','POST',{});
  assert.equal((await c.call('/api/messages/polytechnic-p1','GET')).status,403);
  const match=await c.call('/api/connections','POST',{personId:'polytechnic-p1',action:'connect'});assert.equal(match.body.mutual,true);
  assert.equal((await c.call('/api/messages/polytechnic-p1','POST',{text:'See you at badminton!'})).status,201);
  assert.equal((await c.call('/api/messages/polytechnic-p1','POST',{text:'My Telegram is @testuser'})).status,400);
  assert.equal((await c.call('/api/messages/polytechnic-p1')).body.messages.length,1);
  await c.call('/api/telegram/consent','POST',{personId:'polytechnic-p1',consent:true});await c.call('/api/blocks','POST',{personId:'polytechnic-p1'});
  assert.equal((await c.call('/api/messages/polytechnic-p1')).status,403);assert.equal((await c.call('/api/messages/polytechnic-p1','POST',{text:'Hi'})).status,403);assert.equal((await c.call('/api/telegram/consent','POST',{personId:'polytechnic-p1',consent:true})).status,403);
  const state=(await c.call('/api/state')).body;assert.ok(!state.people.some(p=>p.id==='polytechnic-p1'));assert.ok(!state.conversations.some(p=>p.personId==='polytechnic-p1'));assert.ok(state.activities.every(a=>!a.participants.includes('polytechnic-p1')));
  assert.equal((await c.call('/api/blocks/polytechnic-p1','DELETE')).status,200);assert.equal((await c.call('/api/messages/polytechnic-p1')).status,200);
});

test('OTP rejects false domains, guesses, replay, expiry; live verification fails closed',async t=>{
  const f=await fixture(t),c=f.client();for(const email of ['me@gmail.com','me@ichat.sp.edu.sg.evil.com','me@sp.edu.sg'])assert.equal((await c.call('/api/auth/start','POST',{institutionId:'sp',email})).status,400);
  let start=await c.call('/api/auth/start','POST',{institutionId:'sp',email:'real@ichat.sp.edu.sg'});assert.match(start.body.demoCode,/^\d{6}$/);assert.notEqual(start.body.maskedEmail,'real@ichat.sp.edu.sg');
  assert.equal((await c.call('/api/auth/start','POST',{institutionId:'sp',email:'real@ichat.sp.edu.sg'})).status,429);
  const bad=start.body.demoCode==='000000'?'000001':'000000';assert.equal((await c.call('/api/auth/verify','POST',{challengeId:start.body.challengeId,code:bad})).status,400);
  assert.equal((await c.call('/api/auth/verify','POST',{challengeId:start.body.challengeId,code:start.body.demoCode})).status,200);
  assert.equal((await c.call('/api/auth/verify','POST',{challengeId:start.body.challengeId,code:start.body.demoCode})).status,400);
  start=await c.call('/api/auth/start','POST',{institutionId:'np',email:'expire@connect.np.edu.sg'});f.advance(600001);assert.equal((await c.call('/api/auth/verify','POST',{challengeId:start.body.challengeId,code:start.body.demoCode})).status,400);
  start=await c.call('/api/auth/start','POST',{institutionId:'tp',email:'lock@student.tp.edu.sg'});for(let i=0;i<5;i++)await c.call('/api/auth/verify','POST',{challengeId:start.body.challengeId,code:start.body.demoCode==='000000'?'000001':'000000'});assert.equal((await c.call('/api/auth/verify','POST',{challengeId:start.body.challengeId,code:start.body.demoCode})).status,400);
  const live=await fixture(t,{demoMode:false,resendApiKey:null,mailFrom:null}),lc=live.client();assert.equal((await lc.call('/api/demo','POST',{})).status,404);assert.equal((await lc.call('/api/auth/start','POST',{institutionId:'sp',email:'student@ichat.sp.edu.sg'})).status,503);
});

