test('live email ownership does not claim enrolment or age verification and never returns an OTP',async t=>{
  const originalFetch=globalThis.fetch;let deliveredCode;
  t.mock.method(globalThis,'fetch',async(input,options)=>{if(input==='https://api.resend.com/emails'){const mail=JSON.parse(options.body);deliveredCode=/code is (\d{6})/.exec(mail.text)[1];return new Response(JSON.stringify({id:'local-provider-test'}),{status:200});}return originalFetch(input,options);});
  const f=await fixture(t,{demoMode:false,resendApiKey:'test-provider',mailFrom:'test@example.test'}),c=f.client();
  const start=await c.call('/api/auth/start','POST',{institutionId:'sp',email:'mailbox@ichat.sp.edu.sg',ageBand:'18plus'});assert.equal(start.status,200);assert.equal(start.body.demoCode,undefined);assert.match(deliveredCode,/^\d{6}$/);
  const verify=await c.call('/api/auth/verify','POST',{challengeId:start.body.challengeId,code:deliveredCode});assert.equal(verify.status,200);assert.equal(verify.body.user.emailVerified,true);assert.equal(verify.body.user.enrolmentVerified,false);assert.equal(verify.body.user.ageVerified,false);assert.equal(verify.body.user.verified,false);assert.equal(verify.body.user.verificationMethod,'email');
  const state=(await c.call('/api/state')).body;assert.equal(state.people.length,0);assert.equal(state.activities.length,0);assert.equal(state.circles.length,0);
  const school=(await c.call('/api/institutions?network=secondary')).body.institutions[0];assert.equal((await c.call('/api/auth/start','POST',{institutionId:school.id,email:`mailbox@${school.domains[0]}`,ageBand:'under18'})).status,503);
  assert.equal((await c.call('/api/auth/start','POST',{institutionId:'smu',email:'staff@smu.edu.sg',ageBand:'18plus'})).status,503);
});

