  const db=new DatabaseSync(dbPath),row=db.prepare('SELECT data FROM objects WHERE kind=? AND id=?').get('profile','polytechnic-p1'),profile=JSON.parse(row.data);profile.privateNotes='never public';profile.emergencyContact='never public';profile.reflections=[{text:'never public'}];db.prepare('UPDATE objects SET data=? WHERE kind=? AND id=?').run(JSON.stringify(profile),'profile',profile.id);db.close();
  const c=f.client();await c.call('/api/demo','POST',{});const state=(await c.call('/api/state')).body;for(const person of [state.people.find(p=>p.id===profile.id),state.activities[0].host]){assert.equal(person.privateNotes,undefined);assert.equal(person.emergencyContact,undefined);assert.equal(person.reflections,undefined);assert.equal(person.email,undefined);}
