  assert.equal((await c.call('/api/telegram/consent','POST',{personId:profile.id,consent:true})).body.mutual,true);await c.call('/api/reports','POST',{targetId:profile.id,reason:'Unwanted contact',block:true});await c.call('/api/blocks/'+profile.id,'DELETE');assert.equal((await c.call('/api/telegram/consent','POST',{personId:profile.id,consent:true})).body.mutual,false);
