async function signupClient(f,email,ageBand='18plus',institutionId='sp') {
  const client=f.client(),challenge=(await client.call('/api/auth/start','POST',{institutionId,email,ageBand})).body;
  const verified=await client.call('/api/auth/verify','POST',{challengeId:challenge.challengeId,code:challenge.demoCode});
  assert.equal(verified.status,200);return {client,user:verified.body.user};
}

