test('clubs enforce membership, network, age and blocked-author filtering without opening DMs',async t=>{
  let observeRequest;const f=await fixture(t,{observeRequest:req=>observeRequest?.(req)}),owner=f.client();await owner.call('/api/demo','POST',{});const member=await signupClient(f,'club-member@ichat.sp.edu.sg'),younger=await signupClient(f,'club-younger@ichat.sp.edu.sg','under18'),secondMember=await signupClient(f,'club-second@ichat.sp.edu.sg'),foreign=f.client();await foreign.call('/api/demo','POST',{network:'university'});
  const create=await owner.call('/api/circles','POST',{name:'Weekend explorers',interest:'Photography',description:'Small photo walks and relaxed conversations.',ageBand:'under18'});assert.equal(create.status,201);const c=create.body.circle;assert.equal(c.ownerId,'polytechnic-p0');assert.equal(c.ageBand,'18plus');assert.equal(c.network,'polytechnic');
  assert.equal((await member.client.call('/api/circles/'+c.id+'/messages')).status,200);assert.equal((await member.client.call('/api/circles/'+c.id+'/messages','POST',{text:'Hello everyone'})).status,403);
  assert.equal((await foreign.call('/api/circles/'+c.id)).status,404);assert.equal((await younger.client.call('/api/circles/'+c.id+'/join','POST',{})).status,403);assert.equal((await owner.call('/api/circles','POST',{name:'Wrong network',interest:'Games',description:'A little gathering together.',network:'university'})).status,403);
  const joins=await Promise.all([member.client.call('/api/circles/'+c.id+'/join','POST',{}),secondMember.client.call('/api/circles/'+c.id+'/join','POST',{})]);assert.ok(joins.every(r=>r.status===200));assert.equal((await owner.call('/api/circles/'+c.id)).body.circle.memberCount,3);const message=await member.client.call('/api/circles/'+c.id+'/messages','POST',{text:'A Saturday photo walk sounds good!'});assert.equal(message.status,201);assert.equal(message.body.message.author.email,undefined);assert.equal(message.body.message.author.id,member.user.id);
  assert.equal((await member.client.call('/api/circles/'+c.id+'/messages','POST',{text:'Message me at 9123 4567'})).status,400);assert.equal((await member.client.call('/api/messages/polytechnic-p0','POST',{text:'Direct message'})).status,403);
  assert.equal((await owner.call('/api/circles/'+c.id+'/messages')).body.messages.length,1);
  let arrived;const started=new Promise(resolve=>arrived=resolve);observeRequest=req=>{if(req.method==='POST'&&req.url==='/api/circles/'+c.id+'/messages')arrived();};
  const delayedBody=JSON.stringify({text:'A slow message after access was revoked'});let delayedRequest;const delayedResponse=new Promise((resolve,reject)=>{delayedRequest=httpRequest(f.base+'/api/circles/'+c.id+'/messages',{method:'POST',headers:{Origin:f.base,Cookie:member.client.cookie,'Content-Type':'application/json','Content-Length':Buffer.byteLength(delayedBody)}},res=>{res.resume();res.on('end',()=>resolve(res.statusCode));});delayedRequest.on('error',reject);delayedRequest.write(delayedBody.slice(0,1));});
  await started;await owner.call('/api/blocks','POST',{personId:member.user.id});delayedRequest.end(delayedBody.slice(1));assert.equal(await delayedResponse,403);observeRequest=null;
  assert.equal((await owner.call('/api/circles/'+c.id+'/messages')).body.messages.length,0);assert.equal((await member.client.call('/api/circles/'+c.id+'/messages')).status,403);
  await owner.call('/api/blocks/'+member.user.id,'DELETE');assert.equal((await member.client.call('/api/circles/'+c.id+'/leave','POST',{})).status,200);assert.equal((await member.client.call('/api/circles/'+c.id+'/messages','POST',{text:'After leaving'})).status,403);assert.equal((await owner.call('/api/circles/'+c.id+'/leave','POST',{})).status,400);
});

