test('neighbourhood discovery requires host opt-in and preserves education, age and institution boundaries',async t=>{
  const f=await fixture(t),viewer=f.client(),anonymous=f.client();assert.equal((await anonymous.call('/api/neighbourhood/events')).status,401);
  for(const network of NETWORKS){const client=f.client();await client.call('/api/demo','POST',{network});const feed=await client.call('/api/neighbourhood/events');assert.equal(feed.status,200);assert.equal(feed.body.meta.scope,'neighbourhood');assert.equal(feed.body.meta.network,network);assert.equal(feed.body.meta.partnerImportsAvailable,false);assert.equal(feed.body.activities.length,42);assert.equal(new Set(feed.body.activities.map(a=>a.locationId)).size,10);assert.ok(new Set(feed.body.activities.map(a=>a.institutionId)).size>=5);assert.deepEqual([...new Set(feed.body.activities.map(a=>a.category))].sort(),['events','games','interests','lunch','sports','study']);for(const a of feed.body.activities){const venue=publicMeetingVenues.find(v=>v.id===a.locationId);assert.ok(venue);assert.equal(a.network,network);assert.equal(a.neighbourhoodOptIn,true);assert.equal(a.demoSample,true);assert.match(a.description,/fictional/i);assert.ok(a.date>='2026-09-13');assert.ok(a.participantCount<=a.capacity);assert.equal(a.institutionId,a.host.institutionId);assert.equal(a.institutionLabel,a.host.institution);assert.equal(a.locationDetails.precision,'venue');assert.equal(a.locationDetails.lat,venue.lat);assert.equal(a.locationDetails.lng,venue.lng);if(a.category==='study')assert.equal(a.roleCounts.peer+a.roleCounts.mentor,a.participantCount);}assert.ok(feed.body.activities.some(a=>a.category==='study'&&a.roleCounts.mentor===2));assert.ok(feed.body.activities.some(a=>a.participantCount===a.capacity));}
  await viewer.call('/api/demo','POST',{});const seed=(await viewer.call('/api/neighbourhood/events')).body.activities[0];assert.equal(seed.institutionId,'np');assert.equal(seed.institutionLabel,'Ngee Ann Polytechnic');assert.equal(seed.host.email,undefined);assert.equal((await viewer.call('/api/activities/'+seed.id+'/audience','POST',{neighbourhoodOptIn:false})).status,403);
  const np=await signupClient(f,'neighbourhood-host@connect.np.edu.sg','18plus','np'),younger=await signupClient(f,'neighbourhood-younger@ichat.sp.edu.sg','under18');
  const input={category:'interests',title:'A quiet neighbourhood meetup',description:'Bring a book and meet a few other students.',date:'2026-09-21',time:'14:00',locationId:'np-library',capacity:5,institutionId:'sp'};
  for(const value of ['true',null,1])assert.equal((await np.client.call('/api/activities','POST',{...input,neighbourhoodOptIn:value})).status,400);
  const created=await np.client.call('/api/activities','POST',input);assert.equal(created.status,201);const event=created.body.activity;assert.equal(event.institutionId,'np');assert.equal(event.neighbourhoodOptIn,false);assert.ok(!(await viewer.call('/api/neighbourhood/events')).body.activities.some(a=>a.id===event.id));assert.equal((await viewer.call('/api/activities/'+event.id)).status,200);
  assert.equal((await np.client.call('/api/activities/'+event.id+'/audience','POST',{})).status,400);assert.equal((await viewer.call('/api/activities/'+event.id+'/audience','POST',{neighbourhoodOptIn:true})).status,403);
  const optedIn=await np.client.call('/api/activities/'+event.id+'/audience','POST',{neighbourhoodOptIn:true,network:'university',institutionId:'ntu',hostId:'polytechnic-p0'});assert.equal(optedIn.status,200);assert.equal(optedIn.body.activity.network,'polytechnic');assert.equal(optedIn.body.activity.institutionId,'np');assert.equal(optedIn.body.activity.hostId,np.user.id);assert.ok((await viewer.call('/api/neighbourhood/events')).body.activities.some(a=>a.id===event.id));assert.equal((await viewer.call('/api/activities/'+event.id+'/join','POST',{})).status,200);
  assert.equal((await np.client.call('/api/activities/'+event.id+'/audience','POST',{neighbourhoodOptIn:false})).status,200);assert.ok(!(await viewer.call('/api/neighbourhood/events')).body.activities.some(a=>a.id===event.id));assert.equal((await viewer.call('/api/activities/'+event.id)).body.activity.joined,true);
  const young=await younger.client.call('/api/activities','POST',{...input,locationId:'sp-library',neighbourhoodOptIn:true});assert.equal(young.status,201);assert.ok(!(await viewer.call('/api/neighbourhood/events')).body.activities.some(a=>a.id===young.body.activity.id));assert.deepEqual((await younger.client.call('/api/neighbourhood/events')).body.activities.map(a=>a.id),[young.body.activity.id]);assert.equal((await younger.client.call('/api/activities/'+event.id+'/audience','POST',{neighbourhoodOptIn:true})).status,403);
  const foreign=f.client();await foreign.call('/api/demo','POST',{network:'university'});assert.ok((await foreign.call('/api/neighbourhood/events')).body.activities.every(a=>a.network==='university'));assert.equal((await foreign.call('/api/activities/'+event.id+'/audience','POST',{neighbourhoodOptIn:true})).status,404);
  await np.client.call('/api/activities/'+event.id+'/audience','POST',{neighbourhoodOptIn:true});await viewer.call('/api/blocks','POST',{personId:np.user.id});assert.ok(!(await viewer.call('/api/neighbourhood/events')).body.activities.some(a=>a.id===event.id));
});

test('rich demo migration is reproducible and preserves existing profiles, sessions and activity choices',async t=>{
  const folder=mkdtempSync(join(tmpdir(),'kaki-rich-seed-')),dbPath=join(folder,'rich.sqlite'),f=await fixture(t,{dbPath});t.after(()=>rmSync(folder,{recursive:true,force:true}));const account=await signupClient(f,'refresh-survivor@ichat.sp.edu.sg');
  await account.client.call('/api/profile','PATCH',{bio:'Keep my profile during a demo seed update.'});const existingId='polytechnic-neighbourhood-rich-01';assert.equal((await account.client.call('/api/activities/'+existingId+'/join','POST',{role:'peer'})).status,200);await account.client.call('/api/activities/'+existingId+'/save','POST',{});
  const custom=(await account.client.call('/api/activities','POST',{category:'interests',title:'My own saved gathering',description:'A small gathering created outside the demo seed.',date:'2026-09-22',time:'15:00',locationId:'sp-library',capacity:4,neighbourhoodOptIn:true})).body.activity;
  const db=new DatabaseSync(dbPath),read=(kind,id)=>JSON.parse(db.prepare('SELECT data FROM objects WHERE kind=? AND id=?').get(kind,id).data),write=(kind,p)=>db.prepare('UPDATE objects SET data=? WHERE kind=? AND id=?').run(JSON.stringify(p),kind,p.id);const edited=read('activity',existingId);edited.title='Keep the host’s edited sample title';edited.neighbourhoodOptIn=false;write('activity',edited);const host=read('profile',edited.hostId);host.bio='Keep this existing demo profile edit.';write('profile',host);
  db.prepare('DELETE FROM meta WHERE key=?').run('neighbourhood-rich-demo-v1');db.prepare('DELETE FROM objects WHERE kind=? AND id=?').run('activity','polytechnic-neighbourhood-rich-23');
  const migrated=createApi({dbPath,now:()=>Date.parse('2026-09-13T04:00:00Z')});migrated.close();const once=read('activity',existingId);assert.equal(once.title,edited.title);assert.equal(once.neighbourhoodOptIn,false);assert.deepEqual(once.participants,edited.participants);assert.equal(read('profile',host.id).bio,host.bio);assert.ok(read('activity','polytechnic-neighbourhood-rich-23'));assert.equal(read('activity',custom.id).title,custom.title);assert.equal(db.prepare("SELECT COUNT(*) AS n FROM objects WHERE kind='activity' AND id LIKE '%-neighbourhood-rich-%'").get().n,92);
  const restart=createApi({dbPath,now:()=>Date.parse('2026-09-13T04:00:00Z')});restart.close();assert.equal(db.prepare("SELECT COUNT(*) AS n FROM objects WHERE kind='activity' AND id LIKE '%-neighbourhood-rich-%'").get().n,92);db.close();const state=await account.client.call('/api/state');assert.equal(state.status,200);assert.equal(state.body.user.id,account.user.id);assert.equal(state.body.user.bio,'Keep my profile during a demo seed update.');assert.ok(state.body.user.savedActivityIds.includes(existingId));assert.equal(state.body.activities.find(a=>a.id===existingId).joined,true);
  const jamie=f.client();await jamie.call('/api/demo','POST',{});const club=(await jamie.call('/api/circles/polytechnic-c2')).body.circle;assert.equal(club.joined,true);const messages=(await jamie.call('/api/circles/polytechnic-c2/messages')).body.messages;assert.equal(messages.filter(m=>m.type==='message').length,3);const plan=(await jamie.call('/api/plans/polytechnic-demo-plan')).body.plan;assert.equal(plan.status,'draft');assert.equal(plan.contributionCount,2);const mentors=(await jamie.call('/api/mentors')).body.mentors;assert.equal(mentors.find(p=>p.id==='polytechnic-p2').mentorStats.sessionCount,2);assert.equal(mentors.find(p=>p.id==='polytechnic-p4').mentorStats.isNew,true);assert.equal((await jamie.call('/api/activities/polytechnic-a2')).body.activity.participantRoles['polytechnic-p2'],'mentor');
});

